-- Phase Two Lesson 1.3 released-workbook production: adds section content only.
-- Learners cannot retrieve this section before authenticated scheduled release.
update public.aca_phase_two_workbook_definitions
set content=jsonb_set(content,'{pages}',coalesce(content->'pages','[]'::jsonb)||'{"number":3,"lesson_id":"1.3","kicker":"JOURNEY ONE / LESSON 1.3","title":"Select AI Roles and Define Business Value","blocks":[{"type":"heading","text":"Choose an appropriate AI role"},{"type":"text","text":"Professional AI decisions begin with a clearly defined task, not the novelty of a tool. AI may act as an organizer, neutral question generator, comparison partner, draft assistant, editor, rehearsal partner, or provide no support at all. An AI role supplies assistance; it does not transfer responsibility for approving a price, deadline, promise or sensitive information."},{"type":"note","title":"The decision standard","text":"Choose a role because it serves a real task. If a direct human check, approved template or existing reference is simpler and more dependable, select no AI or a deliberately narrow AI role.","theme":"gold"},{"type":"heading","text":"Activity, output, usefulness and value"},{"type":"text","text":"Activity: a prompt was entered or a draft generated. Output: the result exists. Usefulness: someone can accomplish a relevant task with it. Value: the full process improves a meaningful result after review, corrections, costs and burden shifted to other people have been considered. More pages and faster initial drafts are not proof of greater value."},{"type":"note","title":"Fictional business example","text":"A proposal takes 20 minutes less time to draft with AI, but 30 extra minutes are needed to correct invented promises. The process therefore takes 10 minutes longer, not 20 minutes less. These figures are fictional teaching data, not measured results from your own business.","theme":"gold"},{"type":"field","id":"p2-j1-3-value-definition","label":"What result would constitute genuine value for the person and need you identified in Lesson 1.2?","hint":"Select a useful measure such as fewer corrections, dependable service, clearer decisions or lower end-to-end time.","lines":4},{"type":"heading","text":"Classify five professional tasks"},{"type":"field","id":"p2-j1-3-task1","label":"Task 1 — task, AI role or no AI, human decision, expected benefit, review cost and uncertainty.","hint":"","lines":4},{"type":"field","id":"p2-j1-3-task2","label":"Task 2 — task, AI role or no AI, human decision, expected benefit, review cost and uncertainty.","hint":"","lines":4},{"type":"field","id":"p2-j1-3-task3","label":"Task 3 — task, AI role or no AI, human decision, expected benefit, review cost and uncertainty.","hint":"","lines":4},{"type":"field","id":"p2-j1-3-task4","label":"Task 4 — task, AI role or no AI, human decision, expected benefit, review cost and uncertainty.","hint":"","lines":4},{"type":"field","id":"p2-j1-3-task5","label":"Task 5 — task, AI role or no AI, human decision, expected benefit, review cost and uncertainty.","hint":"","lines":4},{"type":"heading","text":"Use your own AI assistant"},{"type":"text","text":"On a phone, tablet or computer, open your chosen AI assistant. Enter only public, fictional or authorized sanitized task information. Copy the request below. Challenge at least one recommendation and one unsupported claimed benefit. Return to this workbook with your corrected conclusions."},{"type":"note","title":"Copyable AI request","text":"Compare these five tasks by suitable AI support, human decision, likely benefit, added review effort and uncertainty. Include a no-AI option. Do not guarantee savings. Separate supplied facts from assumptions. Tasks: [sanitized task list].","theme":"gold"},{"type":"field","id":"p2-j1-3-ai-correction","label":"What AI recommendation did you challenge or correct?","hint":"Explain why the role was too broad, the claim unverified, or the review effort underestimated.","lines":4},{"type":"heading","text":"Compare AI with a simpler alternative"},{"type":"field","id":"p2-j1-3-baseline","label":"Describe the current method and its baseline. Is the baseline measured, estimated, or unknown?","hint":"","lines":4},{"type":"field","id":"p2-j1-3-options","label":"Compare the proposed AI-supported method with one realistic non-AI option.","hint":"Include end-to-end work time, corrections, risk, who reviews, and who benefits.","lines":4},{"type":"field","id":"p2-j1-3-measure","label":"What measure and fair test would establish whether your approach creates real value?","hint":"Count human review and rework rather than draft speed alone.","lines":4},{"type":"field","id":"p2-j1-3-narrow","label":"Choose a task where AI should have a narrow role or no role. Why?","hint":"","lines":4},{"type":"heading","text":"Your value hypothesis and Project Record"},{"type":"field","id":"p2-j1-3-hypothesis","label":"Write your value hypothesis: person served, task, role, baseline, useful outcome, test, human reviewer and what would change your decision.","hint":"Make no guaranteed savings promise; mark estimated and missing data.","lines":4},{"type":"field","id":"p2-j1-3-check","label":"Explain why 20 minutes saved drafting is not a saving when correcting its output costs 30 minutes.","hint":"State the net result and one non-time measure you would test.","lines":4},{"type":"note","title":"Continue with the same project","text":"Keep your five-task role table and value hypothesis in the existing Project Record begun in Lesson 1.1. Use your workbook for independent study and your Project Record for continuously revised professional evidence. Lesson 1.4 will develop the Professional Request Framework.","theme":"gold"}]}'::jsonb,true),version=version+1,updated_at=now()
where journey_number=1 and not exists (
 select 1 from jsonb_array_elements(content->'pages') p where p->>'lesson_id'='1.3'
);
